#include "point_io.hpp"
#include <chrono>
int main(int argc,char**argv){try{init();if(argc<4)throw runtime_error("usage: evaluate family.txt z0,z1,...,z6 output.json");Fam f=readfam(argv[1]);string zs=argv[2];replace(zs.begin(),zs.end(),',',' ');istringstream ss(zs);vector<F>z(7);for(auto&c:z)ss>>c;if(!ss)throw runtime_error("need 7 parameters");for(F c:z)if(c>=q)throw runtime_error("field codes must be below 390625");Pt p=point(f,z);Poly t=scale(exact(A,Poly{neg(25),1}),inv(13));if(!p.k||pole(p.D2)!=(f.cid?13:12))throw runtime_error("open condition fails");auto start=chrono::steady_clock::now();Poly R=residual(p,t,f.cid,f.r);auto [sq,j]=squaretest(R);cout<<"case="<<f.cid<<" degree="<<deg(R)<<" gcd_degree="<<deg(gcd(R,derivative(R)))<<" square="<<sq<<" seconds="<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";ofstream o(argv[3]);o<<"{\"case\":"<<f.cid<<",\"parameters\":";jpoly(o,z);o<<",\"R0\":";jpoly(o,R);o<<",\"square\":"<<(sq?"true":"false")<<",\"monic_root_candidate\":";jpoly(o,j);o<<"}\n";
}catch(exception&e){cerr<<"ERROR: "<<e.what()<<"\n";return 1;}}
